examples.code:
var fields = new List<DynamicFieldDefinition>
{
    new()
    {
        Name = "FirstName",
        Label = "First Name",
        FieldType = DynamicFieldType.Text,
        IsRequired = true,
        Placeholder = "Enter first name"
    },
    new()
    {
        Name = "Email",
        Label = "Email",
        FieldType = DynamicFieldType.Email,
        IsRequired = true,
        ValidationRules = new()
        {
            new() { RuleType = "email", ErrorMessage = "Invalid email" }
        }
    },
    new()
    {
        Name = "Role",
        Label = "Role",
        FieldType = DynamicFieldType.Select,
        Options = new()
        {
            new() { Value = "user", Text = "User" },
            new() { Value = "admin", Text = "Administrator" }
        }
    },
    new()
    {
        Name = "Department",
        Label = "Department",
        FieldType = DynamicFieldType.Text,
        VisibleWhen = new()
        {
            Field = "Role",
            Operator = "eq",
            Value = "admin"
        }
    }
};

<TmDynamicFormRenderer Fields="@fields" Model="@model" />
